$replacements = @{ "=""#1E1E1E""" = "=""@color/surface2"""; "=""#161616""" = "=""@color/surface"""; "=""#0A0A0A""" = "=""@color/bg_dark"""; "=""#F5F5F5""" = "=""@color/text_primary"""; "=""#666666""" = "=""@color/text_dim"""; "=""#888888""" = "=""@color/text_secondary"""; "=""#2A2A2A""" = "=""@color/border"""; "=""#CCCCCC""" = "=""@color/text_secondary"""; "=""#448AFF""" = "=""@color/tertiary""" }; Get-ChildItem -Path app/src/main/res/layout -Filter "*.xml" | ForEach-Object { $c = Get-Content $_.FullName -Raw; foreach ($k in $replacements.Keys) { $c = $c.Replace($k, $replacements[$k]) }; [System.IO.File]::WriteAllText($_.FullName, $c, [System.Text.Encoding]::UTF8) }
